using Clock=std::chrono::steady_clock;
static void need(bool ok,const std::string& why){if(!ok)throw std::runtime_error(why);}
static std::string strip(std::string s){if(!s.empty()&&s.back()=='\r')s.pop_back();if(s.size()>=3&&s.substr(0,3)=="\xef\xbb\xbf")s.erase(0,3);return s;}
static std::vector<std::string> split(const std::string& s,char sep){std::vector<std::string> a;std::istringstream f(s);std::string v;while(std::getline(f,v,sep))a.push_back(v);if(!s.empty()&&s.back()==sep)a.emplace_back();return a;}
static std::uint64_t number(const std::string& s){need(!s.empty()&&s.find_first_not_of("0123456789")==std::string::npos,"invalid integer "+s);std::size_t n=0;auto x=std::stoull(s,&n);need(n==s.size(),"integer suffix");return x;}
static std::map<std::string,std::size_t> columns(const std::string& s,char sep){std::map<std::string,std::size_t> c;auto a=split(strip(s),sep);for(std::size_t i=0;i<a.size();++i)need(c.emplace(a[i],i).second,"duplicate column");return c;}
static std::string field(const std::vector<std::string>& row,const std::map<std::string,std::size_t>& c,const std::string& n){auto i=c.find(n);need(i!=c.end()&&i->second<row.size(),"missing field "+n);return row[i->second];}
static fs::path path8(const std::string& s){return fs::path(std::u8string(reinterpret_cast<const char8_t*>(s.data()),s.size()));}
static std::string quote(const std::string& s){std::ostringstream o;o<<'"';for(unsigned char c:s){if(c=='"'||c=='\\')o<<'\\'<<c;else if(c<32)o<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<int(c)<<std::dec;else o<<c;}o<<'"';return o.str();}
static std::vector<std::uint8_t> read_bytes(const fs::path& p){std::ifstream f(p,std::ios::binary|std::ios::ate);need(bool(f),"read "+p.string());auto n=f.tellg();need(n>=0&&n<=4000000,"corpus byte bound");std::vector<std::uint8_t>b(static_cast<std::size_t>(n));f.seekg(0);f.read(reinterpret_cast<char*>(b.data()),n);need(bool(f),"short read");return b;}
static std::uint64_t le(const std::uint8_t*p,unsigned n){std::uint64_t v=0;for(unsigned i=0;i<n;++i)v|=std::uint64_t(p[i])<<(8*i);return v;}
struct Frame{Packet dp,sp;Dense d{};Sparse s{};Features expected{};};
struct Case{std::string id;std::uint64_t threshold=0,dense_bytes=0,sparse_bytes=0,visited=0;fs::path dense_path,sparse_path,features_path;std::vector<Frame> frames;};
static void packets(Case& c,bool sparse){auto b=read_bytes(sparse?c.sparse_path:c.dense_path);std::size_t offset=0;for(std::size_t i=0;i<3001;++i){need(b.size()-offset>=48,"truncated packet header");auto payload=le(b.data()+offset+12,4);need(payload<=1032,"payload bound");auto n=static_cast<std::size_t>((48+payload+7)&~std::uint64_t{7});need(n<=max_packet&&n<=b.size()-offset,"packet size bound");auto& f=c.frames[i];auto& p=sparse?f.sp:f.dp;p.size=n;std::copy_n(b.data()+offset,n,p.bytes.data());if(sparse){decode_sparse(p.view(),{i,c.threshold},f.s);c.visited+=f.s.count;}else decode_dense(p.view(),{i,c.threshold},f.d);offset+=n;}need(offset==b.size(),"trailing corpus bytes/extra frames");(sparse?c.sparse_bytes:c.dense_bytes)=b.size();}
static void admit(Case& c){c.frames.resize(3001);packets(c,false);packets(c,true);std::ifstream f(c.features_path);need(bool(f),"expected CSV missing");std::string line;need(bool(std::getline(f,line)),"expected CSV empty");auto col=columns(line,',');need(col.size()==17,"expected CSV columns");std::size_t i=0;while(std::getline(f,line)){line=strip(line);need(!line.empty(),"blank feature row");auto row=split(line,',');need(row.size()==17&&i<3001&&number(field(row,col,"frame_idx"))==i,"feature frame sequence");for(std::size_t k=0;k<bands;++k)c.frames[i].expected[k]=number(field(row,col,"band"+std::to_string(k)));++i;}need(i==3001,"feature frame count");for(const auto& x:c.frames){Dense expanded{};for(std::size_t k=0;k<x.s.count;++k)expanded[x.s.entries[k]&255]=x.s.entries[k]>>8;need(expanded==x.d,"dense/sparse input mismatch");Features d{},s{};consume_dense(x.d,d);consume_sparse(x.s,s);need(d==x.expected&&s==x.expected,"feature oracle mismatch");}}
static std::vector<Case> load(const fs::path& list){std::ifstream f(list);need(bool(f),"TSV missing");std::string line;need(bool(std::getline(f,line)),"TSV empty");auto col=columns(line,'\t');need(col.size()==5||col.size()==6,"TSV column count");std::vector<Case> out;std::set<std::string> ids;std::set<std::uint64_t> thresholds;while(std::getline(f,line)){line=strip(line);need(!line.empty(),"blank TSV row");auto r=split(line,'\t');need(r.size()==col.size(),"TSV row width");Case c;c.id=field(r,col,"case_id");need(!c.id.empty()&&c.id.find_first_of(",\r\n\"/\\")==std::string::npos&&ids.insert(c.id).second,"case ID");c.threshold=number(field(r,col,"threshold"));need(thresholds.insert(c.threshold).second,"duplicate threshold");if(col.count("frames"))need(number(field(r,col,"frames"))==3001,"frames must3001");auto resolve=[&](const char* name){auto p=path8(field(r,col,name));return p.is_absolute()?p:(list.parent_path()/p);};c.dense_path=resolve("dense");c.sparse_path=resolve("sparse");c.features_path=resolve("expected_features");admit(c);out.push_back(std::move(c));}need(thresholds==std::set<std::uint64_t>{0,100000000,1000000000,10000000000,100000000000},"exact five thresholds required");return out;}
struct Workspace{std::vector<Dense>d;std::vector<Sparse>s;std::vector<Features>f;Workspace():d(3001),s(3001),f(3001){}};
static void kernel(const Case& c,bool sparse,bool decode,std::size_t repeats,Workspace& w){for(std::size_t rep=0;rep<repeats;++rep)for(std::size_t i=0;i<c.frames.size();++i){const auto& f=c.frames[i];if(decode){if(sparse){decode_sparse(f.sp.view(),{i,c.threshold},w.s[i]);consume_sparse(w.s[i],w.f[i]);}else{decode_dense(f.dp.view(),{i,c.threshold},w.d[i]);consume_dense(w.d[i],w.f[i]);}}else if(sparse)consume_sparse(f.s,w.f[i]);else consume_dense(f.d,w.f[i]);observe(w.f[i].data(),sizeof(Features));}}
static void validate(const Case& c,bool sparse,bool decode,const Workspace&w){for(std::size_t i=0;i<c.frames.size();++i){const auto& f=c.frames[i];need(w.f[i]==f.expected,"trial output mismatch");if(decode){if(sparse)need(w.s[i].count==f.s.count&&std::equal(f.s.entries.begin(),f.s.entries.begin()+f.s.count,w.s[i].entries.begin()),"trial sparse decode mismatch");else need(w.d[i]==f.d,"trial dense decode mismatch");}}}
static std::uint64_t cpu_ns(){FILETIME create,exit,kernel,user;need(GetThreadTimes(GetCurrentThread(),&create,&exit,&kernel,&user)!=0,"GetThreadTimes failed");return ((std::uint64_t(kernel.dwHighDateTime)<<32|kernel.dwLowDateTime)+(std::uint64_t(user.dwHighDateTime)<<32|user.dwLowDateTime))*100;}
struct Timing{std::int64_t wall;std::uint64_t cpu;};
static Timing timed(const Case& c,bool sparse,bool decode,std::size_t repeats,Workspace&w){auto cpu0=cpu_ns();auto wall0=Clock::now();kernel(c,sparse,decode,repeats,w);auto wall1=Clock::now();auto cpu1=cpu_ns();validate(c,sparse,decode,w);return {std::chrono::duration_cast<std::chrono::nanoseconds>(wall1-wall0).count(),cpu1-cpu0};}
static std::string cpu_name(){int x[4];__cpuid(x,static_cast<int>(0x80000000));if(static_cast<unsigned>(x[0])<0x80000004)return "unavailable";char name[49]{};for(int j=0;j<3;++j){__cpuid(x,static_cast<int>(0x80000002)+j);std::memcpy(name+16*j,x,16);}return name;}
int main(int argc,char**argv){try{
#ifndef NDEBUG
throw std::runtime_error("Release build required");
#endif
fs::path input,out;bool run=false,validation=false;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--cases"&&i+1<argc)input=path8(argv[++i]);else if(a=="--out"&&i+1<argc)out=path8(argv[++i]);else if(a=="--run")run=true;else if(a=="--validate-only")validation=true;else throw std::runtime_error("unknown/incomplete argument "+a);}need(!input.empty()&&!out.empty()&&(run!=validation),"use --cases TSV --out FRESH and exactly --validate-only or --run");need(!fs::exists(out),"fresh output required");auto cases=load(fs::absolute(input));fs::create_directories(out);std::ofstream meta(out/"metadata.json");meta.exceptions(std::ios::failbit|std::ios::badbit);DWORD_PTR process_mask=0,system_mask=0;need(GetProcessAffinityMask(GetCurrentProcess(),&process_mask,&system_mask)!=0,"affinity query");SYSTEM_INFO system{};GetNativeSystemInfo(&system);meta<<"{\n\"schema\":\"trecap-downstream8-native-v1\",\n\"mode\":"<<quote(run?"TIMING":"VALIDATE_ONLY")<<",\n\"compiler\":"<<quote("MSVC "+std::to_string(_MSC_FULL_VER))<<",\n\"cpu\":"<<quote(cpu_name())<<",\n\"logical_processors\":"<<system.dwNumberOfProcessors<<",\n\"process_affinity_mask\":"<<process_mask<<",\n\"process_priority\":"<<GetPriorityClass(GetCurrentProcess())<<",\n\"wall_clock\":\"std::chrono::steady_clock; primary metric\",\n\"wall_period_num\":"<<Clock::period::num<<",\n\"wall_period_den\":"<<Clock::period::den<<",\n\"cpu_clock\":\"GetThreadTimes current thread kernel+user;100ns units, effective accounting granularity may be coarse\",\n\"build\":\"Release O2 GL- LTCG:OFF; identical opaque observer per frame; no encoding, allocation or I/O in interval\",\n\"trials\":30,\n\"warmups\":3,\n\"calibration_target_fastest_wall_ns\":20000000,\n\"repeat_bound\":[1,1024],\n\"cases\":[\n";
std::ofstream raw;if(run){raw.open(out/"raw_trials.csv");raw.exceptions(std::ios::failbit|std::ios::badbit);raw<<"trial,case_id,threshold,stage,mode,repeats,frames,wall_ns,cpu_ns,warmup,pair_order\n";}
std::uint64_t records=0,zero_cpu=0,min_cpu=~std::uint64_t{0};
for(std::size_t ci=0;ci<cases.size();++ci){const auto& c=cases[ci];Workspace w;if(ci)meta<<",\n";meta<<"{\"case_id\":"<<quote(c.id)<<",\"threshold\":"<<c.threshold<<",\"frames\":3001,\"dense_bytes\":"<<c.dense_bytes<<",\"sparse_bytes\":"<<c.sparse_bytes<<",\"dense_visited_bins_per_pass\":387129,\"sparse_visited_bins_per_pass\":"<<c.visited<<",\"stages\":[";
for(int st=0;st<2;++st){bool decode=st!=0;const char* stage=decode?"decode_consumer":"consumer";if(st)meta<<',';std::size_t repeats=1;Timing d{},s{};if(run){for(;;){d=timed(c,false,decode,repeats,w);s=timed(c,true,decode,repeats,w);if(std::min(d.wall,s.wall)>=20000000||repeats==1024)break;repeats*=2;}}else for(bool sparse:{false,true}){kernel(c,sparse,decode,1,w);validate(c,sparse,decode,w);}
meta<<"{\"stage\":"<<quote(stage)<<",\"repeats\":"<<repeats<<",\"calibration_dense_wall_ns\":"<<d.wall<<",\"calibration_sparse_wall_ns\":"<<s.wall<<",\"target_reached\":"<<(run&&std::min(d.wall,s.wall)>=20000000?"true":"false")<<'}';
if(run)for(int trial=-3;trial<30;++trial){bool first_sparse=((trial+3)%2)!=0;for(int order=0;order<2;++order){bool sparse=order==0?first_sparse:!first_sparse;auto t=timed(c,sparse,decode,repeats,w);raw<<trial<<','<<c.id<<','<<c.threshold<<','<<stage<<','<<(sparse?"sparse":"dense")<<','<<repeats<<",3001,"<<t.wall<<','<<t.cpu<<','<<(trial<0?1:0)<<','<<order<<'\n';++records;if(t.cpu==0)++zero_cpu;else min_cpu=std::min(min_cpu,t.cpu);}}}
meta<<"]}";if(run)raw.flush();std::cout<<"PASS "<<c.id<<'\n';}
meta<<"\n],\n\"raw_records\":"<<records<<",\n\"zero_cpu_time_records\":"<<zero_cpu<<",\n\"min_positive_cpu_ns\":"<<(min_cpu==~std::uint64_t{0}?0:min_cpu)<<",\n\"observer\":"<<observer_value()<<",\n\"status\":\"PASS\",\n\"limitations\":\"Packet-input downstream CPU experiment; validation outside timed interval; cached preallocated data; no producer/transport/AI inference/power/utilization claim. CPU deltas may be too coarse; use wall primary.\"\n}\n";std::cout<<(run?"TIMING PASS":"VALIDATE_ONLY PASS")<<'\n';return 0;
}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
